// Nursing Assisting Practice Test 6. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–5.
import {q, mix} from './q.js';
const DUG='Dugan, Nursing Assisting: A Foundation in Caregiving', ROE='Roe, The Nursing Assistant: Essentials of Holistic Care';
const ROLE='Nursing Assistant Roles and Responsibilities', AP='Anatomy and Physiology', INF='Infection Control/Safety', COMM='Communication/Culture', CARE='Providing and Reporting Care', DIS='Disabilities and Disorders';

export default {
 id:'nursing-assisting-6',
 event:'Nursing Assisting',
 title:'Practice Test 6',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Dugan’s Nursing Assisting: A Foundation in Caregiving and Roe’s The Nursing Assistant',
 plan:[{area:ROLE,weight:6},{area:AP,weight:20},{area:INF,weight:14},{area:COMM,weight:10},{area:CARE,weight:30},{area:DIS,weight:20}],
 questions:mix([
  q(ROLE,'What is needed before a physical restraint may be used on a resident?','A physician’s order and a documented medical reason',['A family member’s verbal request, made at any time during the resident’s stay','The nursing assistant’s own judgment','A note from another resident'],'A','Restraints are a last resort; staff must try less restrictive alternatives first.',DUG),
  q(ROLE,'A nursing assistant keeps a resident alone in her room as punishment for being loud. What is this?','Involuntary seclusion, a form of abuse',['Appropriate behavior management','A resident right','Normal quiet time'],'B','Confining a resident against their will is abuse and must be reported.',DUG),
  q(ROLE,'Under federal rules, how many hours of in-service education must nursing assistants complete each year?','At least 12 hours',['At least 1 hour','At least 4 hours','At least 100 hours'],'C','Annual training keeps skills current, often covering dementia care and abuse prevention.',DUG),
  q(AP,'Which smooth, rubbery tissue covers the ends of bones and cushions joints?','Cartilage',['Ligament','Tendon','Marrow'],'D','When cartilage wears away, as in osteoarthritis, bones rub together and cause pain.',ROE),
  q(AP,'Which blood vessels carry oxygen-poor blood from the heart to the lungs?','Pulmonary arteries',['Pulmonary veins','Coronary arteries','The aorta'],'A','The pulmonary arteries are the only arteries that carry oxygen-poor blood.',ROE),
  q(AP,'What is the tube that carries air from the larynx to the bronchi?','Trachea',['Esophagus','Pharynx','Alveolus'],'B','The trachea is held open by C-shaped rings of cartilage and branches into the two bronchi.',ROE),
  q(AP,'Which tube carries food from the throat to the stomach?','Esophagus',['Trachea','Duodenum','Colon'],'C','Peristalsis, a wave of muscle contractions, moves food down the esophagus into the stomach.',ROE),
  q(AP,'Which tube carries urine from the bladder out of the body?','Urethra',['Ureter','Renal pelvis','Nephron'],'D','The female urethra is short, which is one reason women get more urinary tract infections.',ROE),
  q(AP,'Which spiral-shaped structure in the inner ear changes sound waves into nerve signals?','Cochlea',['Semicircular canals','Eardrum','Eustachian tube'],'A','Damage to the hair cells in the cochlea causes much of age-related hearing loss.',ROE),
  q(AP,'Which gland at the base of the brain controls many other endocrine glands?','Pituitary gland',['Thyroid gland','Adrenal gland','Pancreas'],'B','The pituitary is often called the master gland because it controls the thyroid, adrenals and others.',ROE),
  q(AP,'Which small structures filter lymph and trap germs, often swelling during infection?','Lymph nodes',['Alveoli in the lungs','Nephrons in the kidneys','Villi in the small intestine'],'C','Swollen lymph nodes in the neck, armpits or groin may signal infection.',ROE),
  q(AP,'Which type of muscle moves the bones and is under voluntary control?','Skeletal muscle',['Cardiac muscle','Smooth muscle','Visceral muscle'],'D','Smooth muscle in organs and cardiac muscle in the heart work without conscious control.',ROE),
  q(AP,'Where does fertilization of an egg by a sperm usually take place?','In the fallopian tube',['In the ovary, where the egg forms','In the vagina, just after release','In the cervix, at the uterine opening'],'A','The fertilized egg then travels down the tube to the uterus, where it implants in the lining.',ROE),
  q(INF,'What is the difference between disinfection and sterilization?','Sterilization kills all microorganisms, including spores; disinfection kills most',['Disinfection kills spores; sterilization kills only some bacteria','They mean exactly the same thing and can be used interchangeably','Sterilization is only done with soap and warm water at the sink'],'B','Sterilization is needed for items that enter sterile body areas, such as surgical instruments.',DUG),
  q(INF,'Which bacterium is resistant to many common antibiotics and spreads mainly by touch?','MRSA (methicillin-resistant Staphylococcus aureus)',['Influenza virus spread by droplets','Tuberculosis bacteria spread through the air','Measles virus spread through the air'],'C','Contact precautions, hand hygiene and cleaning surfaces help prevent MRSA spread.',DUG),
  q(INF,'Why are older residents in nursing homes more likely to get infections?','They are more susceptible hosts because of weaker immunity and chronic illness',['They have stronger immune systems than younger people, so infections are mild and rare','They are never exposed to germs','They always receive antibiotics'],'D','Aging, illness, catheters and wounds all make residents more vulnerable.',DUG),
  q(INF,'Where should soiled linen be placed after removing it from a bed?','Directly into the laundry hamper or bag, never on the floor',['On the floor until the bed is made','On the resident’s chair until the end of the shift','On the overbed table next to the meal tray'],'A','Placing soiled linen on surfaces or floors spreads germs; hold it away from your uniform too.',DUG),
  q(INF,'Which vaccine must employers offer free to workers who may be exposed to blood?','Hepatitis B vaccine',['Chickenpox vaccine','Rabies vaccine','Yellow fever vaccine'],'B','OSHA’s Bloodborne Pathogens Standard requires employers to offer the hepatitis B vaccine.',DUG),
  q(INF,'When can bed side rails be considered a restraint?','When they keep a resident from getting out of bed as they wish',['Never, because side rails are always safe and cannot hold anyone in bed','Only when they are painted a certain color','Only when the bed is in the lowest position'],'C','Side rails can cause entrapment and injury; they need an assessment and order.',DUG),
  q(INF,'Where can staff find information about the hazards of a cleaning chemical?','The Safety Data Sheet (SDS)',['The resident’s care plan','The menu board','The visitor log'],'D','SDSs list hazards, safe handling, PPE and first aid for each chemical.',DUG),
  q(COMM,'A grieving resident is crying quietly. How can silence be therapeutic?','Sitting quietly nearby shows support and gives time to share feelings',['Silence means the assistant does not care about the resident','Silence should always be filled with jokes to cheer the resident up','Silence is only helpful during meals and bedtime routines'],'A','Being present without rushing to talk can comfort and encourage sharing.',ROE),
  q(COMM,'Why should nursing assistants avoid “elderspeak,” such as calling residents “honey” or using baby talk?','It can seem disrespectful and make residents feel less capable',['It is always required by facility policy for residents over the age of 80','It improves hearing in older adults','It helps residents remember names'],'B','Use the resident’s preferred name and speak as one adult to another.',ROE),
  q(COMM,'A resident from another culture avoids eye contact during conversation. What should the assistant understand?','In some cultures, avoiding eye contact is a sign of respect',['It always means the resident is lying or hiding something from the staff','It means the resident cannot hear','It shows the resident is angry'],'C','Nonverbal behaviors differ across cultures and should not be judged by one standard.',ROE),
  q(COMM,'Why should an assistant ask before moving close to a resident who is not receiving care?','People have different comfort levels with personal space',['Residents never allow anyone near them','It is against the law to stand near residents','It helps the assistant hear better'],'D','Respecting personal space builds trust; during care, explain before moving in close.',ROE),
  q(COMM,'How should a nursing assistant give instructions to a resident with dementia?','Use short, simple, one-step directions',['Give all instructions at once in detail','Write long notes for the resident to read','Speak quickly to finish the task'],'A','Breaking tasks into single steps reduces confusion and frustration.',ROE),
  q(CARE,'The apical pulse is 92 and the radial pulse is 80. What is the difference called?','Pulse deficit',['Pulse pressure','Blood pressure','Respiratory rate'],'B','A pulse deficit means some heartbeats are not reaching the wrist, often due to an irregular rhythm.',DUG),
  q(CARE,'A resident rates pain as 8 on a 0–10 scale. What should the assistant do?','Report it to the nurse right away',['Wait until the next shift','Tell the resident it is not that bad','Give the resident pain medicine'],'C','Pain is what the resident says it is; prompt reporting allows timely treatment.',DUG),
  q(CARE,'How is a 24-hour urine collection usually started?','Have the resident void and discard that first urine, then collect all urine for 24 hours',['Collect only the first morning urine and send it to the lab','Collect a single cup of urine at any time of day or night and label it as a 24-hour specimen','Save urine only when the resident remembers to use the hat'],'D','The test ends with a final void at the same time the next day, which is added to the container.',DUG),
  q(CARE,'How many staff members are usually needed to move a resident with a mechanical lift?','At least two',['One','None, the resident operates it','At least six'],'A','Two staff keep the resident safe and steady the sling during the transfer.',DUG),
  q(CARE,'What does the order “NPO” mean?','Nothing by mouth',['No pain observed','Nurse present only','Normal portions only'],'B','Residents may be NPO before tests or surgery; remove the water pitcher and post a sign.',DUG),
  q(CARE,'What is the main purpose of a sitz bath?','To clean and soothe the perineal or rectal area',['To wash the hair of a resident on bed rest','To lower a high fever by cooling the whole body','To soak the feet and soften thick toenails'],'C','Sitz baths increase blood flow and ease pain after childbirth or rectal surgery.',DUG),
  q(CARE,'Why do residents use an incentive spirometer after surgery?','To encourage deep breaths and prevent lung problems',['To measure blood sugar levels before meals','To check blood pressure without using a cuff','To give oxygen to residents who cannot breathe'],'D','Deep breathing expands the lungs and helps prevent pneumonia.',DUG),
  q(CARE,'A bladder training program is ordered. What does the assistant usually do?','Offer the toilet on a regular schedule, such as every 2 hours',['Limit all fluids to almost none during the day','Use adult briefs only, without offering the toilet','Wait until the resident is wet, then change them'],'A','Regular toileting helps residents regain control and stay dry.',DUG),
  q(CARE,'A resident lies flat on the stomach with the head turned to one side. Which position is this?','Prone',['Supine','Fowler’s','Sims'],'B','Supine is lying on the back; prone is lying on the stomach, with pillows used for support.',DUG),
  q(CARE,'What is a normal pulse oximetry reading for most healthy adults?','About 95% to 100%',['About 50% to 60%','About 70% to 80%','About 105% to 110%'],'C','A reading below the resident’s normal or under about 90% should be reported right away.',DUG),
  q(CARE,'A resident wants to leave the facility to visit family for the afternoon. What should the nursing assistant do?','Tell the nurse so the plan and medications can be arranged',['Lock the door so the resident cannot leave','Tell the resident they are not allowed to leave','Let them leave without telling anyone'],'D','Residents have the right to leave the facility; the nurse handles the sign-out and any medications.',DUG),
  q(CARE,'How should urine be measured in a graduate for output?','On a flat surface at eye level',['While holding it above the head','By guessing from the color','On the resident’s lap'],'A','Reading at eye level on a flat surface gives an accurate measurement.',DUG),
  q(CARE,'A resident has a new cast on the arm. Which finding should be reported right away?','Numbness, tingling or cold fingers',['The cast feels dry','The resident can wiggle the fingers','The fingers are pink and warm'],'B','These signs may mean the cast is too tight and is cutting off circulation.',DUG),
  q(CARE,'Which sign may suggest dehydration in an older resident?','Dark yellow urine and dry mouth',['Pale yellow urine and moist lips','Frequent large amounts of urine','Weight gain and swelling'],'C','Older adults may not feel thirsty, so offer fluids often and report signs of dehydration.',DUG),
  q(CARE,'At what angle should a toothbrush be held against the gumline?','About 45 degrees',['About 90 degrees','Flat against the teeth','Pointing away from the gums'],'D','Gentle short strokes at a 45-degree angle clean plaque near the gums.',DUG),
  q(DIS,'A spinal cord injury in the lower back causes paralysis of the legs. What is this called?','Paraplegia',['Quadriplegia','Hemiplegia','Tetraplegia'],'A','Residents with paraplegia often use wheelchairs and need pressure relief.',ROE),
  q(DIS,'Why is high blood pressure called a “silent” disease?','It often has no symptoms until damage occurs',['It makes people lose their voice','It only happens during sleep','It always causes severe headaches'],'B','Regular blood pressure checks find hypertension before it causes strokes or heart attacks.',ROE),
  q(DIS,'Which heart attack symptoms are more common in women?','Shortness of breath, nausea, fatigue and back or jaw pain',['Only sudden crushing pain in the center of the chest','A raised, itchy rash on both arms and legs','Increased appetite and thirst over several weeks'],'C','Women may not have classic chest pain; any of these symptoms should be reported.',ROE),
  q(DIS,'An older resident has a cough, fever and trouble breathing. Which infection of the lungs is likely?','Pneumonia',['Cystitis','Conjunctivitis','Cellulitis'],'D','Pneumonia is a common cause of illness in older adults and may also cause new confusion.',ROE),
  q(DIS,'Which symptoms may suggest tuberculosis?','A long-lasting cough, night sweats and weight loss',['Itchy skin, sneezing and watery eyes in spring','A sudden swelling of one ankle after a fall','Hearing loss and ringing in both ears'],'A','TB spreads through the air, so residents are placed on airborne precautions.',ROE),
  q(DIS,'Which eye disease raises pressure inside the eye and slowly destroys side vision?','Glaucoma',['Cataract','Macular degeneration','Conjunctivitis'],'B','Untreated glaucoma can cause blindness; residents may use daily eye drops.',ROE),
  q(DIS,'A resident hears voices that others do not hear. Which mental illness can cause this?','Schizophrenia',['Osteoarthritis','Asthma','Hypothyroidism'],'C','Do not argue about the voices; stay calm and report changes to the nurse.',ROE),
  q(DIS,'A resident is pale, tired and short of breath with activity because of a low red blood cell count. What is this?','Anemia',['Hypertension','Hyperglycemia','Edema'],'D','Anemia reduces oxygen delivery; plan rest periods and report dizziness.',ROE),
  q(DIS,'After a fall, a resident has hip pain and one leg looks shorter and turned outward. What should be suspected?','A hip fracture',['A sprained ankle','A muscle cramp','A bruise only'],'A','Do not move the resident; keep them still and comfortable and call the nurse right away.',ROE),
  q(DIS,'A resident has below-average intellectual ability and needs help with daily living skills since childhood. What is this?','Intellectual disability',['Dementia from Alzheimer disease','Delirium from an infection','Major depression'],'B','Intellectual disability begins before age 18, while dementia develops later in life.',ROE)
 ],9612)
};
